create extension if not exists pgcrypto;
do $$ begin create type public.user_role as enum('user','content_editor','event_manager','administrator'); exception when duplicate_object then null; end $$;
do $$ begin create type public.content_type as enum('video','podcast','article','resource','printable','pick','event','recipe','original'); exception when duplicate_object then null; end $$;
do $$ begin create type public.content_status as enum('draft','published','archived'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role public.user_role not null default 'user',membership_tier text not null default 'personal' check(membership_tier in('personal','family','school')),membership_status text not null default 'inactive' check(membership_status in('pending_payment','pending_school_code','active','past_due','canceled','inactive','expired')),stripe_customer_id text,stripe_subscription_id text,membership_period_end timestamptz,cancel_at_period_end boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.content(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text not null default '',type public.content_type not null default 'video',category text,tags text[] not null default '{}',cover_url text,media_url text,media_provider_id text,duration text,member_only boolean not null default false,featured boolean not null default false,status public.content_status not null default 'draft',published_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.sections(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text not null default '',is_published boolean not null default false,sort_order int not null default 0,created_at timestamptz not null default now());
create table if not exists public.section_content(section_id uuid references public.sections(id) on delete cascade,content_id uuid references public.content(id) on delete cascade,sort_order int not null default 0,primary key(section_id,content_id));
create table if not exists public.favorites(user_id uuid references public.profiles(id) on delete cascade,content_id uuid references public.content(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,content_id));
create table if not exists public.watch_progress(user_id uuid references public.profiles(id) on delete cascade,content_id uuid references public.content(id) on delete cascade,position_seconds int not null default 0,duration_seconds int,updated_at timestamptz not null default now(),primary key(user_id,content_id));
create table if not exists public.content_views(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,content_id uuid references public.content(id) on delete cascade,viewed_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',starts_at timestamptz not null,ends_at timestamptz,location text,registration_url text,image_url text,status public.content_status not null default 'draft',created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.inquiries(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('contact','school')),name text not null,email text not null,subject text not null default '',message text not null default '',metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists content_status_date_idx on public.content(status,published_at desc); create index if not exists events_status_date_idx on public.events(status,starts_at);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,display_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.content enable row level security; alter table public.sections enable row level security; alter table public.section_content enable row level security; alter table public.favorites enable row level security; alter table public.watch_progress enable row level security; alter table public.content_views enable row level security; alter table public.events enable row level security; alter table public.inquiries enable row level security;
create policy "profile read self" on public.profiles for select to authenticated using(id=auth.uid());
create policy "published content visible" on public.content for select to authenticated using(status='published' and (not member_only or exists(select 1 from public.profiles p where p.id=auth.uid() and p.membership_status='active')));
create policy "admin content all" on public.content for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='administrator')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='administrator'));
create policy "published sections visible" on public.sections for select to authenticated using(is_published=true);
create policy "admin sections all" on public.sections for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='administrator')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='administrator'));
create policy "published section content visible" on public.section_content for select to authenticated using(exists(select 1 from public.sections s where s.id=section_id and s.is_published=true));
create policy "favorites own" on public.favorites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "watch progress own" on public.watch_progress for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "views own" on public.content_views for select to authenticated using(user_id=auth.uid()); create policy "views insert own" on public.content_views for insert to authenticated with check(user_id=auth.uid());
create policy "published events public" on public.events for select to anon,authenticated using(status='published');
create policy "admin events all" on public.events for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='administrator')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='administrator'));
create policy "public inquiry insert" on public.inquiries for insert to anon,authenticated with check(kind in('contact','school'));
-- Before launch, add admin inquiry read policy and tightly constrain profile updates. Do not allow users to change role or membership fields.
